// Lights Out — turn every light off. Pure vanilla JS, fully offline.
// Modes: Classic (no clock), Time Attack (countdown), Daily (seeded), Zen (untimed).
// Boards are generated by replaying random presses from an all-off board, so
// every puzzle is guaranteed solvable. Hints use a real GF(2) linear solver,
// so they stay correct even after you deviate from the generated solution.
//
// Shared plumbing comes from ../../js/arcade-core.js.
(() => {
  "use strict";

  const {
    store,
    keys: makeKeys,
    util,
    audio,
    toast,
    overlay,
    confetti,
    badges: badgesApi,
    modal: modalApi,
    dom,
  } = window.Arcade;

  const { formatTime, hashSeed, mulberry32 } = util;
  const sfx = audio.sfx;
  const showToast = toast.show;
  const showOverlay = overlay.show;
  const hideOverlay = overlay.hide;
  const createBadges = badgesApi.create;
  const createModal = modalApi.create;

  // ---------- DOM ----------
  const boardEl = dom.byId("board");
  const boardWrap = dom.byId("board-wrap");
  const countdownEl = dom.byId("countdown");
  const countdownNumEl = dom.byId("countdown-num");
  const timeEl = dom.byId("time");
  const movesEl = dom.byId("moves");
  const lightsEl = dom.byId("lights");
  const scoreEl = dom.byId("score");
  const solvedEl = dom.byId("solved");
  const hintsEl = dom.byId("hints");
  const bestEl = dom.byId("best");
  const hintEl = dom.byId("hint");
  const liveEl = dom.byId("live");

  const pauseBtn = dom.byId("pause");
  const hintBtn = dom.byId("hint-btn");
  const newGameBtn = dom.byId("new-game");
  const finishBtn = dom.byId("finish");
  const badgesBtn = dom.byId("badges-btn");
  const badgeCountEl = dom.byId("badge-count");
  const soundBtn = dom.byId("sound-btn");
  const soundIconEl = dom.byId("sound-icon");

  const modeChips = dom.all(".mode-chip");
  const diffChips = dom.all(".diff-chip");

  const achvModal = dom.byId("achv-modal");
  const achvGrid = dom.byId("achv-grid");
  const achvCountEl = dom.byId("achv-count");
  const achvRecordsEl = dom.byId("achv-records");

  toast.bind(dom.byId("toasts"));

  // ---------- Constants ----------
  const MODES = {
    classic: { name: "Classic", timed: false, hints: 3 },
    attack: { name: "Time Attack", timed: true, hints: 2 },
    daily: { name: "Daily", timed: false, hints: 3 },
    zen: { name: "Zen", timed: false, hints: Infinity },
  };

  const DIFFS = {
    easy: { name: "Easy", size: 3, presses: 4, attackTime: 90, par: 4 },
    normal: { name: "Normal", size: 4, presses: 8, attackTime: 120, par: 8 },
    hard: { name: "Hard", size: 5, presses: 13, attackTime: 150, par: 13 },
  };

  const ACHIEVEMENTS = [
    { id: "first", icon: "💡", name: "Lights Out", desc: "Solve your first board.", stat: "solved", goal: 1 },
    { id: "solved10", icon: "🔟", name: "Ten Boards", desc: "Solve 10 boards.", stat: "solved", goal: 10 },
    { id: "solved50", icon: "🏅", name: "Grid Master", desc: "Solve 50 boards.", stat: "solved", goal: 50 },
    { id: "perfect", icon: "🎯", name: "Optimal", desc: "Solve a board in the minimum number of moves.", stat: "perfect", goal: 1 },
    { id: "perfect10", icon: "💎", name: "Optimal Ten", desc: "Solve 10 boards optimally.", stat: "perfect", goal: 10 },
    { id: "hard", icon: "🔥", name: "Hard Mode", desc: "Solve a 5 × 5 board.", stat: "hardWins", goal: 1 },
    { id: "hard10", icon: "🌋", name: "Hard Veteran", desc: "Solve 10 hard boards.", stat: "hardWins", goal: 10 },
    { id: "attack", icon: "⏱️", name: "Beat the Clock", desc: "Solve a board in Time Attack.", stat: "attackWins", goal: 1 },
    { id: "attack5", icon: "🚀", name: "Blitz", desc: "Solve 5 boards in one Time Attack round.", stat: "attackBest", goal: 5 },
    { id: "daily", icon: "📅", name: "Daily Habit", desc: "Solve the Daily board.", stat: "dailySolves", goal: 1 },
    { id: "daily3", icon: "🗓️", name: "Three in a Row", desc: "Reach a 3-day daily streak.", stat: "dailyStreak", goal: 3 },
    { id: "daily7", icon: "📆", name: "Week Warrior", desc: "Reach a 7-day daily streak.", stat: "dailyStreak", goal: 7 },
    { id: "noHint", icon: "🛡️", name: "Pure Logic", desc: "Solve a board without a hint.", stat: "noHintWins", goal: 1 },
    { id: "noHint10", icon: "🧠", name: "Unassisted", desc: "Solve 10 boards without a hint.", stat: "noHintWins", goal: 10 },
    { id: "hint", icon: "💡", name: "Helping Hand", desc: "Use a hint.", stat: "hintsUsed", goal: 1 },
    { id: "zen", icon: "🌿", name: "Zen Master", desc: "Solve a Zen board.", stat: "zenWins", goal: 1 },
    { id: "speed", icon: "⚡", name: "Quick Thinker", desc: "Solve an Easy board in under 10 seconds.", stat: "speed", goal: 1 },
    { id: "noMistake", icon: "✨", name: "Flawless", desc: "Solve a Hard board without ever re-pressing a cell.", stat: "cleanHard", goal: 1 },
    { id: "night", icon: "🦉", name: "Night Owl", desc: "Solve a board between midnight and 5 AM.", stat: "nightWins", goal: 1 },
    { id: "score300", icon: "🌟", name: "High Scorer", desc: "Score 300+ in one round.", stat: "bestScore", goal: 300 },
    { id: "score800", icon: "👑", name: "Lights Royalty", desc: "Score 800+ in one round.", stat: "bestScore", goal: 800 },
    { id: "streak5", icon: "🔥", name: "On a Roll", desc: "Solve 5 boards in a row without a restart.", stat: "bestStreak", goal: 5 },
    { id: "moves", icon: "🧮", name: "Efficient", desc: "Solve a Normal board in 8 moves or fewer.", stat: "bestMovesNormal", goal: 8, invert: true },
    { id: "total", icon: "🔢", name: "Lights Keeper", desc: "Solve 100 boards in total.", stat: "solved", goal: 100 },
  ];

  const DEFAULT_STATS = {
    solved: 0,
    bestScore: 0,
    perfect: 0,
    hardWins: 0,
    attackWins: 0,
    attackBest: 0,
    dailySolves: 0,
    noHintWins: 0,
    hintsUsed: 0,
    zenWins: 0,
    speed: 0,
    cleanHard: 0,
    nightWins: 0,
    bestStreak: 0,
    streak: 0,
    bestMovesNormal: Infinity,
    playTime: 0,
  };

  const K = makeKeys("lights-out");

  // ---------- Persistent state ----------
  const storedStats = store.json(K.stats, {});
  const stats = Object.assign(
    {},
    DEFAULT_STATS,
    storedStats && typeof storedStats === "object" && !Array.isArray(storedStats) ? storedStats : {}
  );
  for (const key of Object.keys(DEFAULT_STATS)) {
    if (!Number.isFinite(stats[key])) stats[key] = DEFAULT_STATS[key];
  }
  if (stats.bestMovesNormal === null) stats.bestMovesNormal = Infinity;

  let daily = store.json(K.daily, null);
  if (!daily || typeof daily !== "object" || Array.isArray(daily)) {
    daily = { streak: 0, lastDate: "", history: {} };
  }
  if (!daily.history || typeof daily.history !== "object") daily.history = {};
  if (!Number.isFinite(daily.streak)) daily.streak = 0;

  // ---------- Audio ----------
  audio.bindButton({ btn: soundBtn, icon: soundIconEl, soundKey: K.sound });

  // ---------- State ----------
  const state = {
    mode: "classic",
    diff: "easy",
    size: 3,
    grid: [],
    initial: [],
    moves: 0,
    presses: {},      // cell index -> times pressed this board
    score: 0,
    solved: 0,        // boards solved this round
    hintsLeft: 3,
    hintsUsed: 0,
    elapsed: 0,
    remaining: 0,
    countdown: 0,
    started: false,
    paused: false,
    over: false,
    perfect: true,
    streak: 0,
  };

  let cellEls = [];
  let resumeAfterModal = false;
  let lastTs = 0;
  let lastTimeText = "";
  let hintTimer = 0;

  // ---------- Achievements ----------
  function statValue(key) {
    if (key === "dailyStreak") return daily.streak;
    if (key === "bestMovesNormal") {
      if (!Number.isFinite(stats.bestMovesNormal)) return 0;
      return Math.max(0, 9 - stats.bestMovesNormal);
    }
    return stats[key] || 0;
  }

  function saveStats() {
    store.jsonSet(K.stats, stats);
  }

  const achv = createBadges(ACHIEVEMENTS, {
    storageKey: K.achv,
    getStat: statValue,
    onUnlock: () => {
      updateBadgeCount();
      saveStats();
    },
    onRender: () => {
      if (!achvModal.hidden) renderAchvGrid();
    },
  });

  function checkAchievements() {
    achv.check();
  }

  function updateBadgeCount() {
    badgeCountEl.textContent = achv.count();
    badgesBtn.setAttribute(
      "aria-label",
      `Badges and achievements: ${achv.count()} of ${achv.total()} unlocked`
    );
  }

  function renderAchvGrid() {
    achv.render(achvGrid, {
      countEl: achvCountEl,
      recordsEl: achvRecordsEl,
      records: () => [
        ["Best", stats.bestScore],
        ["Solved", stats.solved],
        ["Optimal", stats.perfect],
        ["Daily streak", daily.streak + "d"],
        ["Best streak", stats.bestStreak],
      ],
    });
  }

  const achvModalCtl = createModal(achvModal, {
    onOpen: () => {
      renderAchvGrid();
      if (!state.over && !state.paused && state.started) {
        state.paused = true;
        resumeAfterModal = true;
        pauseBtn.textContent = "▶ Resume";
      }
    },
    onClose: () => {
      if (resumeAfterModal) {
        resumeAfterModal = false;
        if (!state.over) {
          state.paused = false;
          pauseBtn.textContent = "Pause";
        }
      }
      const target = overlay.isOpen() ? document.querySelector(".overlay .btn") : badgesBtn;
      if (target && target.focus) target.focus();
    },
  });

  function openAchv() {
    achvModalCtl.open();
  }

  function closeAchv() {
    achvModalCtl.close();
  }

  // ---------- Lights Out maths ----------
  /** Cells toggled by pressing `i` on an n×n board. */
  function neighbours(i, n) {
    const r = Math.floor(i / n);
    const c = i % n;
    const res = [i];
    if (r > 0) res.push(i - n);
    if (r < n - 1) res.push(i + n);
    if (c > 0) res.push(i - 1);
    if (c < n - 1) res.push(i + 1);
    return res;
  }

  function applyPress(grid, i, n) {
    for (const j of neighbours(i, n)) grid[j] = !grid[j];
  }

  /**
   * Solve "turn every light off" over GF(2).
   * Returns the minimum-weight set of presses, or null if unsolvable.
   * Board sizes here top out at 5×5, where the null space has dimension 2,
   * so enumerating it is cheap and gives a genuinely optimal hint.
   */
  function solveLights(grid, n) {
    const N = n * n;
    // rows: N equations, cols: N unknowns + 1 rhs
    const rows = [];
    for (let i = 0; i < N; i++) {
      const row = new Uint8Array(N + 1);
      for (const j of neighbours(i, n)) row[j] = 1;
      row[N] = grid[i] ? 1 : 0;
      rows.push(row);
    }

    const pivotOfCol = new Int32Array(N).fill(-1);
    let rank = 0;
    for (let col = 0; col < N && rank < N; col++) {
      let sel = -1;
      for (let r = rank; r < N; r++) {
        if (rows[r][col]) {
          sel = r;
          break;
        }
      }
      if (sel < 0) continue;
      const tmp = rows[rank];
      rows[rank] = rows[sel];
      rows[sel] = tmp;
      for (let r = 0; r < N; r++) {
        if (r !== rank && rows[r][col]) {
          for (let c = col; c <= N; c++) rows[r][c] ^= rows[rank][c];
        }
      }
      pivotOfCol[col] = rank;
      rank++;
    }

    // Inconsistent?
    for (let r = rank; r < N; r++) {
      let any = false;
      for (let c = 0; c < N; c++) if (rows[r][c]) { any = true; break; }
      if (!any && rows[r][N]) return null;
    }

    // A particular solution: free vars = 0.
    const base = new Uint8Array(N);
    for (let col = 0; col < N; col++) {
      const r = pivotOfCol[col];
      if (r >= 0) base[col] = rows[r][N];
    }

    // Null-space basis vectors.
    const freeCols = [];
    for (let col = 0; col < N; col++) if (pivotOfCol[col] < 0) freeCols.push(col);
    const basis = [];
    for (const free of freeCols) {
      const v = new Uint8Array(N);
      v[free] = 1;
      for (let col = 0; col < N; col++) {
        const r = pivotOfCol[col];
        if (r >= 0 && rows[r][free]) v[col] = 1;
      }
      basis.push(v);
    }

    // Enumerate the (small) solution space, keep the lightest.
    let best = base;
    let bestWeight = weight(base);
    const combos = 1 << basis.length;
    for (let mask = 1; mask < combos; mask++) {
      const v = base.slice();
      for (let b = 0; b < basis.length; b++) {
        if (mask & (1 << b)) {
          const bv = basis[b];
          for (let i = 0; i < N; i++) v[i] ^= bv[i];
        }
      }
      const w = weight(v);
      if (w < bestWeight) {
        bestWeight = w;
        best = v;
      }
    }

    const presses = [];
    for (let i = 0; i < N; i++) if (best[i]) presses.push(i);
    return presses;
  }

  function weight(v) {
    let w = 0;
    for (let i = 0; i < v.length; i++) w += v[i];
    return w;
  }

  // ---------- Board generation ----------
  function generatePuzzle(rand, n, presses) {
    const N = n * n;
    const grid = new Array(N).fill(false);
    const picks = new Set();
    let guard = 0;
    while (picks.size < presses && guard++ < 500) {
      picks.add(Math.floor(rand() * N));
    }
    for (const i of picks) applyPress(grid, i, n);
    // Guarantee the board isn't already solved.
    if (grid.every((v) => !v)) applyPress(grid, Math.floor(rand() * N), n);
    return grid;
  }

  // ---------- Rendering ----------
  function buildBoard() {
    while (boardEl.firstChild) boardEl.removeChild(boardEl.firstChild);
    boardEl.style.gridTemplateColumns = `repeat(${state.size}, 1fr)`;
    boardEl.dataset.size = String(state.size);
    cellEls = [];

    for (let i = 0; i < state.size * state.size; i++) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "lo-cell";
      btn.dataset.idx = String(i);
      btn.setAttribute("aria-pressed", "false");
      btn.addEventListener("click", () => onCellClick(i));
      boardEl.appendChild(btn);
      cellEls.push(btn);
    }
  }

  function renderCells() {
    const r = Math.floor((cellEls.length ? 0 : 0));
    for (let i = 0; i < cellEls.length; i++) {
      const el = cellEls[i];
      const on = !!state.grid[i];
      el.classList.toggle("is-on", on);
      el.setAttribute("aria-pressed", on ? "true" : "false");
      el.setAttribute(
        "aria-label",
        `Row ${Math.floor(i / state.size) + 1}, column ${(i % state.size) + 1}: light ${on ? "on" : "off"}`
      );
    }
  }

  function countLights() {
    let n = 0;
    for (const v of state.grid) if (v) n++;
    return n;
  }

  function updateHUD() {
    timeEl.textContent = MODES[state.mode].timed
      ? formatTime(state.remaining)
      : formatTime(state.elapsed);
    movesEl.textContent = String(state.moves);
    lightsEl.textContent = String(countLights());
    scoreEl.textContent = String(state.score);
    solvedEl.textContent = String(state.solved);
    hintsEl.textContent = state.mode === "zen" ? "∞" : String(state.hintsLeft);
    bestEl.textContent = bestLabel();

    hintBtn.disabled = state.mode !== "zen" && state.hintsLeft <= 0;
    hintBtn.textContent = state.mode === "zen" ? "💡 Hint ∞" : `💡 Hint (${state.hintsLeft})`;
    finishBtn.disabled = !state.started || state.over;
  }

  function updateTimeDisplay() {
    const text = MODES[state.mode].timed
      ? formatTime(state.remaining)
      : formatTime(state.elapsed);
    if (text !== lastTimeText) {
      lastTimeText = text;
      timeEl.textContent = text;
    }
    timeEl.classList.toggle(
      "is-danger",
      MODES[state.mode].timed && state.remaining <= 15000 && state.started && !state.over
    );
  }

  function updateCountdown() {
    if (state.started || state.countdown <= 0) {
      countdownEl.hidden = true;
      return;
    }
    countdownEl.hidden = false;
    const label = String(Math.min(3, Math.max(1, Math.ceil(state.countdown / 400))));
    if (countdownNumEl.textContent !== label) {
      countdownNumEl.textContent = label;
      countdownNumEl.style.animation = "none";
      void countdownNumEl.offsetWidth;
      countdownNumEl.style.animation = "";
    }
  }

  function updateHint() {
    const d = DIFFS[state.diff];
    const m = MODES[state.mode];
    let text;
    if (state.mode === "attack") text = `Time Attack · ${d.size}×${d.size} · ${d.attackTime}s`;
    else if (state.mode === "daily") text = `Daily · ${d.size}×${d.size} · streak ${daily.streak}d`;
    else if (state.mode === "zen") text = `Zen · ${d.size}×${d.size} · unlimited hints`;
    else text = `Classic · ${d.size}×${d.size} · no clock`;
    hintEl.textContent =
      text +
      " · Turn every light OFF · Clicking toggles a cell and its orthogonal neighbours · Fewer moves score more · H hint, P pause";
  }

  function updateModeUI() {
    modeChips.forEach((b) =>
      b.setAttribute("aria-pressed", b.dataset.mode === state.mode ? "true" : "false")
    );
    diffChips.forEach((b) =>
      b.setAttribute("aria-pressed", b.dataset.diff === state.diff ? "true" : "false")
    );
    newGameBtn.disabled = state.mode === "daily";
    finishBtn.hidden = state.mode !== "zen";
    updateHint();
    updateHUD();
  }

  function bestLabel() {
    const rec = store.json(K.best(state.mode, state.diff), null);
    if (!rec || !rec.s) return "—";
    return String(rec.s);
  }

  // ---------- Game flow ----------
  function newPuzzle(opts) {
    hideOverlay();
    window.clearTimeout(hintTimer);

    const keepClock = !!(opts && opts.keepClock);
    const keepStarted = !!(opts && opts.keepStarted);
    const seed = state.mode === "daily" ? `${util.dateStr()}-${state.diff}` : null;
    const rand = seed ? mulberry32(hashSeed(seed)) : Math.random;

    const d = DIFFS[state.diff];
    state.size = d.size;
    state.grid = generatePuzzle(rand, d.size, d.presses);
    state.initial = state.grid.slice();
    state.moves = 0;
    state.presses = {};
    state.perfect = true;
    state.hintsUsed = 0;
    state.hintsLeft = MODES[state.mode].hints;

    if (keepClock) {
      // Same round, next board — the clock and score carry on.
      state.over = false;
      state.paused = false;
    } else {
      // Fresh round.
      state.score = 0;
      state.solved = 0;
      state.elapsed = 0;
      state.remaining = MODES[state.mode].timed ? d.attackTime * 1000 : 0;
      state.over = false;
      state.paused = false;
      state.streak = 0;
    }

    if (keepStarted && state.started) {
      // Flow straight into the next board with no countdown.
      state.countdown = 0;
    } else {
      state.countdown = 1200;
      state.started = false;
    }

    lastTimeText = "";
    pauseBtn.textContent = "Pause";

    buildBoard();
    renderCells();
    updateModeUI();
    updateCountdown();
    updateTimeDisplay();
    updateHUD();

    boardWrap.classList.remove("is-shaking");
    void boardWrap.offsetWidth;
    boardWrap.classList.add("is-shaking");
    window.setTimeout(() => boardWrap.classList.remove("is-shaking"), 460);

    lastTs = performance.now();
  }

  function setMode(m) {
    if (!MODES[m] || m === state.mode) return;
    state.mode = m;
    store.set(K.mode, m);
    updateModeUI();
    newPuzzle();
  }

  function setDiff(d) {
    if (!DIFFS[d] || d === state.diff) return;
    state.diff = d;
    state.size = DIFFS[d].size;
    store.set(K.diff, d);
    updateModeUI();
    newPuzzle();
  }

  function startPlay() {
    if (state.started) return;
    state.started = true;
    state.countdown = 0;
    updateCountdown();
    sfx("click");
    updateHUD();
  }

  // ---------- Play ----------
  function onCellClick(i) {
    if (!canEdit()) return;

    applyPress(state.grid, i, state.size);
    state.moves++;
    state.presses[i] = (state.presses[i] || 0) + 1;
    if (state.presses[i] > 1) state.perfect = false;

    sfx("toggle");
    renderCells();
    updateHUD();

    if (countLights() === 0) {
      boardSolved();
    } else {
      dom.announce(liveEl, `${countLights()} lights remaining.`);
    }
  }

  function boardSolved() {
    const d = DIFFS[state.diff];
    const optimal = solveLights(state.initial, state.size);
    const par = optimal ? optimal.length : d.par;
    const isOptimal = state.moves === par;

    state.solved++;
    if (isOptimal) stats.perfect++;

    // Score: base by size, efficiency bonus, hint penalty.
    const base = d.size * d.size * 4;
    const efficiency = Math.max(0, par * 2 - state.moves) * 6;
    const hintPenalty = state.hintsUsed * 25;
    const boardScore = Math.max(10, base + efficiency - hintPenalty);
    state.score += boardScore;

    stats.solved++;
    stats.bestScore = Math.max(stats.bestScore, state.score);
    if (state.diff === "hard") {
      stats.hardWins++;
      if (state.perfect && Object.keys(state.presses).length === par) stats.cleanHard = 1;
    }
    if (state.hintsUsed === 0) stats.noHintWins++;
    if (state.diff === "normal" && state.moves <= 8) {
      stats.bestMovesNormal = Math.min(stats.bestMovesNormal, state.moves);
    }
    if (state.mode === "attack") {
      stats.attackWins++;
      stats.attackBest = Math.max(stats.attackBest, state.solved);
    }
    if (state.mode === "zen") stats.zenWins++;
    if (state.diff === "easy" && state.elapsed < 10000 && state.mode !== "attack") stats.speed = 1;
    if (new Date().getHours() < 5) stats.nightWins++;

    state.streak++;
    stats.streak = state.streak;
    stats.bestStreak = Math.max(stats.bestStreak, state.streak);
    saveStats();
    checkAchievements();

    sfx(isOptimal ? "match" : "word");
    showToast(
      isOptimal ? "Optimal! 🎯" : "Solved! 💡",
      `${state.moves} moves · +${boardScore} points`,
      isOptimal ? "🎯" : "💡"
    );
    if (isOptimal) confetti(60);

    // Record best score / moves for this mode + difficulty.
    const prev = store.json(K.best(state.mode, state.diff), null);
    const prevScore = prev && Number.isFinite(prev.s) ? prev.s : 0;
    if (state.score > prevScore || !prev) {
      store.jsonSet(K.best(state.mode, state.diff), {
        s: state.score,
        m: state.moves,
      });
    }

    if (state.mode === "daily") {
      recordDailyWin(boardScore, state.moves);
      endRound("clear");
      return;
    }

    if (state.mode === "attack") {
      // Keep the clock running, deal a fresh board.
      window.setTimeout(() => {
        if (!state.over) newPuzzle({ keepClock: true, keepStarted: true });
      }, 550);
      return;
    }

    // Classic / Zen: brief pause, then the next board straight away.
    window.setTimeout(() => {
      if (!state.over) newPuzzle({ keepStarted: true });
    }, 650);
  }

  function useHint() {
    if (!canEdit()) return;
    if (state.mode !== "zen" && state.hintsLeft <= 0) {
      showToast("No hints left", "You've used all your hints for this board.", "💡");
      sfx("error");
      return;
    }

    const solution = solveLights(state.grid, state.size);
    if (!solution || !solution.length) {
      showToast("Already solved", "No lights are on.", "✨");
      return;
    }

    // Suggest a press from a minimum solution for the *current* board.
    const pick = solution[0];
    state.hintsUsed++;
    stats.hintsUsed++;
    if (state.mode !== "zen") state.hintsLeft--;
    saveStats();
    checkAchievements();

    const cell = cellEls[pick];
    if (cell) {
      cell.classList.add("is-hint");
      window.clearTimeout(hintTimer);
      hintTimer = window.setTimeout(() => {
        if (cell.classList) cell.classList.remove("is-hint");
      }, 2200);
    }

    sfx("hint");
    showToast(
      "Try this one",
      `Row ${Math.floor(pick / state.size) + 1}, column ${(pick % state.size) + 1} · ${solution.length} moves left`,
      "💡"
    );
    dom.announce(
      liveEl,
      `Hint: row ${Math.floor(pick / state.size) + 1}, column ${(pick % state.size) + 1}.`
    );
    updateHUD();
  }

  // ---------- End / score ----------
  function endRound(reason) {
    if (state.over) return;
    state.over = true;
    state.paused = false;

    stats.playTime += Math.round(state.elapsed);
    saveStats();
    checkAchievements();
    updateHUD();

    const won = state.solved > 0;
    sfx(won ? "win" : "over");
    if (won) confetti(70);

    const title = won
      ? state.solved > 1
        ? `${state.solved} Boards Cleared! 🎉`
        : "Board Cleared! 💡"
      : "Time's up! ⏰";
    const msg =
      `${DIFFS[state.diff].size}×${DIFFS[state.diff].size} · ` +
      `${state.solved} solved · ${state.moves} moves this board · ` +
      `${formatTime(state.elapsed)} · Score ${state.score}`;

    showOverlay(title, msg, [
      { label: "Play Again", onClick: () => { hideOverlay(); newPuzzle(); } },
      { label: "Badges", ghost: true, onClick: () => openAchv() },
      { label: "Change Mode", ghost: true, onClick: () => { hideOverlay(); focusModeBar(); } },
    ]);
  }

  function recordDailyWin(boardScore, moves) {
    if (state.mode !== "daily") return;
    const today = util.dateStr();
    if (daily.lastDate === today) return;
    daily.streak = daily.lastDate === util.yesterdayStr() ? daily.streak + 1 : 1;
    daily.lastDate = today;
    daily.history[today] = { s: boardScore, m: moves, d: state.diff };
    const keys = Object.keys(daily.history).sort();
    while (keys.length > 21) delete daily.history[keys.shift()];
    stats.dailySolves++;
    store.jsonSet(K.daily, daily);
    saveStats();
  }

  function canEdit() {
    return state.started && !state.paused && !state.over && achvModal.hidden;
  }

  function focusModeBar() {
    const chip = document.querySelector(".mode-chip");
    if (chip) chip.focus();
  }

  function setPaused(p, silent) {
    if (state.over || !state.started) return;
    state.paused = p;
    pauseBtn.textContent = p ? "▶ Resume" : "Pause";
    if (p && !silent) {
      showOverlay("Paused", "Take a breath — press P or hit Resume.", [
        { label: "Resume", onClick: () => { hideOverlay(); setPaused(false, true); } },
        { label: "Restart", ghost: true, onClick: () => { hideOverlay(); newPuzzle(); } },
      ]);
    } else if (!p) {
      hideOverlay();
    }
  }

  function togglePause() {
    if (state.over || !state.started) return;
    setPaused(!state.paused, false);
  }

  // ---------- Loop ----------
  function loop(ts) {
    requestAnimationFrame(loop);
    if (!lastTs) lastTs = ts;
    let dt = ts - lastTs;
    lastTs = ts;
    if (dt > 100) dt = 100;

    if (!state.started && !state.over && !state.paused && achvModal.hidden) {
      state.countdown = Math.max(0, state.countdown - dt);
      if (state.countdown === 0) startPlay();
      updateCountdown();
    }

    if (state.started && !state.over && !state.paused && achvModal.hidden) {
      state.elapsed += dt;
      if (MODES[state.mode].timed) {
        state.remaining -= dt;
        if (state.remaining <= 0) {
          state.remaining = 0;
          updateTimeDisplay();
          endRound("time");
          return;
        }
      }
    }

    updateTimeDisplay();
  }

  // ---------- Input ----------
  function onKeyDown(e) {
    const k = e.key;
    const lower = k.toLowerCase();

    if (!achvModal.hidden) {
      if (k === "Escape") {
        closeAchv();
        e.preventDefault();
      }
      return;
    }

    const tag = ((e.target && e.target.tagName) || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select") return;
    if (tag === "button" && (k === " " || k === "Enter")) return;

    if (k === "Escape") {
      if (state.paused) {
        setPaused(false, true);
        e.preventDefault();
      }
      return;
    }

    if (lower === "p") {
      e.preventDefault();
      togglePause();
      return;
    }

    if (state.over) {
      if (k === "Enter" || k === " ") {
        e.preventDefault();
        newPuzzle();
      }
      return;
    }

    if (state.paused) return;

    if (lower === "h") {
      useHint();
      return;
    }

    if (lower === "n" && state.mode !== "daily") {
      newPuzzle();
    }
  }

  function bindEvents() {
    modeChips.forEach((btn) => {
      btn.addEventListener("click", () => {
        const m = btn.dataset.mode;
        if (!MODES[m] || m === state.mode) return;
        sfx("click");
        setMode(m);
      });
    });

    diffChips.forEach((btn) => {
      btn.addEventListener("click", () => {
        const d = btn.dataset.diff;
        if (!DIFFS[d] || d === state.diff) return;
        sfx("click");
        setDiff(d);
      });
    });

    hintBtn.addEventListener("click", useHint);
    newGameBtn.addEventListener("click", () => {
      sfx("click");
      if (state.mode !== "daily") newPuzzle();
    });
    pauseBtn.addEventListener("click", () => {
      sfx("click");
      togglePause();
    });
    finishBtn.addEventListener("click", () => {
      sfx("click");
      endRound("manual");
    });

    badgesBtn.addEventListener("click", () => {
      sfx("click");
      openAchv();
    });
    const badges2 = dom.byId("badges2");
    if (badges2) {
      badges2.addEventListener("click", () => {
        sfx("click");
        openAchv();
      });
    }

    document.addEventListener("keydown", onKeyDown);

    window.addEventListener("blur", () => {
      if (!state.over && !state.paused && state.started && achvModal.hidden) {
        setPaused(true, false);
      }
    });
    document.addEventListener("visibilitychange", () => {
      if (document.hidden && !state.over && !state.paused && state.started && achvModal.hidden) {
        setPaused(true, false);
      }
    });

    audio.bindUnlock();
  }

  // ---------- Init ----------
  function init() {
    const savedDiff = store.get(K.diff, "easy");
    state.diff = DIFFS[savedDiff] ? savedDiff : "easy";
    state.size = DIFFS[state.diff].size;

    const savedMode = store.get(K.mode, "classic");
    state.mode = MODES[savedMode] ? savedMode : "classic";

    updateBadgeCount();
    bindEvents();
    newPuzzle();
    renderAchvGrid();
    requestAnimationFrame(loop);
  }

  // Test hook — harmless in normal play.
  window.__LO = {
    state,
    stats,
    daily,
    MODES,
    DIFFS,
    ACHIEVEMENTS,
    neighbours,
    applyPress,
    solveLights,
    generatePuzzle,
    newPuzzle: (opts) => newPuzzle(opts),
    setMode,
    setDiff,
    startPlay,
    onCellClick,
    useHint,
    endRound,
    checkAchievements,
    saveStats,
    loop,
    setPaused,
    togglePause,
    countLights,
    unlocked: () => achv.list(),
    snap: () => ({
      mode: state.mode,
      diff: state.diff,
      size: state.size,
      grid: state.grid.slice(),
      initial: state.initial.slice(),
      moves: state.moves,
      lights: countLights(),
      score: state.score,
      solved: state.solved,
      hintsLeft: state.hintsLeft,
      hintsUsed: state.hintsUsed,
      elapsed: state.elapsed,
      remaining: state.remaining,
      started: state.started,
      paused: state.paused,
      over: state.over,
      perfect: state.perfect,
      cellEls: cellEls.length,
      stats: Object.assign({}, stats),
      daily: Object.assign({}, daily),
      unlocked: achv.list(),
      overlayTitle: overlay.info().title,
      overlayMsg: overlay.info().msg,
    }),
  };

  init();
})();